import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { detectMimeType, pdfText, sha256Hex } from '#src/lib/file-processing';

// Generated by test/fixtures/uploads/generate.py (pdf skill: reportlab + pypdf).
const VALID_PDF = readFileSync('test/fixtures/uploads/valid.pdf');
const PDF_RENAMED_DOCX = readFileSync('test/fixtures/uploads/pdf-renamed.docx');

describe('file processing on real fixtures', () => {
  it('detects a PDF by its bytes, also when it is named .docx', async () => {
    expect(await detectMimeType(VALID_PDF)).toBe('application/pdf');
    expect(await detectMimeType(PDF_RENAMED_DOCX)).toBe('application/pdf');
    expect(await detectMimeType(Buffer.from('just some text'))).toBeUndefined();
  });

  it('extracts the PDF text for search', async () => {
    expect(await pdfText(VALID_PDF)).toContain('trusslattice');
  });

  it('hashes bytes', () => {
    expect(sha256Hex(Buffer.from('abc'))).toBe(
      'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad',
    );
  });
});
